        from collections import deque
        visited = set()
        rooms = []

        for i in range(n):
            for j in range(m):
                if grid[i][j] == '.' and (i, j) not in visited:
                    room = []
                    q = deque([(i, j)])
                    visited.add((i, j))
                    room.append((i, j))
                    visited.add((i, j))

                    while q:
                        x, y = q.popleft()
                        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
