# Solution for the XOR operation problem

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, u, r = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    k = list(map(int, lines[3].split()))
    p = list(map(int, lines[4].split()))
    p = [x - 1 for x in p]  # Convert to 0-indexed

    def compute_score(arr):
        return sum(arr[i] ^ b[i] for i in range(n))

    from functools import lru_cache

    # Use memoization - convert array to tuple for hashable state
    @lru_cache(maxsize=None)
    def max_score(arr_tuple, remaining_ops):
        if remaining_ops == 0:
            return compute_score(arr_tuple)

        # Operation 1: XOR with k
        new_xor = tuple((arr_tuple[i] ^ k[i]) for i in range(n))
        # Operation 2: Permutation + r
        new_perm = tuple((arr_tuple[p[i]] + r) for i in range(n))

        return max(max_score(new_xor, remaining_ops - 1),
                   max_score(new_perm, remaining_ops - 1))

    return str(max_score(tuple(a), u))
