def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Build implication graph
    # Node mapping: x_i -> 2*i-1, -x_i -> 2*i
    adj = {}
    for i in range(1, 2 * m + 1):
        adj[i] = []

    def get_node(lit):
        if lit > 0:
            return 2 * lit - 1  # positive literal
        else:
            return 2 * abs(lit)  # negative literal

    # Read clauses and build implications
    for i in range(1, n + 1):
        parts = lines[i].split()
        k = int(parts[0])
        literals = list(map(int, parts[1:]))

        # For clause (l1 ∨ l2 ∨ ... ∨ lk), add ¬li -> lj for each pair
        for idx in range(k):
            lit = literals[idx]
            not_lit = -lit
            from_node = get_node(not_lit)

            for jdx in range(k):
                if jdx != idx:
                    other = literals[jdx]
                    to_node = get_node(other)
                    adj[from_node].append(to_node)

    # Tarjan's SCC algorithm
    ids = [0] * (2 * m + 2)
    low = [0] * (2 * m + 2)
    scc = [-1] * (2 * m + 2)
    on_stack = [False] * (2 * m + 2)
    stack = []
    id_count = [0]
    scc_count = [0]
    dfs_ids = []

    def dfs(at):
        ids[at] = low[at] = id_count[0]
        id_count[0] += 1
        stack.append(at)
        on_stack[at] = True

        for to in adj[at]:
            if ids[to] == 0:
                dfs(to)
                low[at] = min(low[at], low[to])
            elif on_stack[to]:
                low[at] = min(low[at], ids[to])

        if ids[at] == low[at]:
            while stack:
                node = stack.pop()
                on_stack[node] = False
                scc[node] = scc_count[0]
                if node == at:
                    break
            scc_count[0] += 1

    for i in range(1, 2 * m + 1):
        if ids[i] == 0:
            dfs(i)

    # Check SATISFIABILITY: x and ¬x shouldn't be in same SCC
    for i in range(1, m + 1):
        if scc[2 * i - 1] == scc[2 * i]:
            return "NO"

    # Build assignment
    result = []
    for i in range(1, m + 1):
        if scc[2 * i - 1] < scc[2 * i]:
            result.append('1')
        else:
            result.append('0')

    return "YES\n" + "".join(result)
