    if not data:
        return "0"
    n = int(data[0])
    a = [list(map(int, data[i].split())) for i in range(1, n + 1)]

    # Precompute factorials
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = fact[i-1] * i % MOD

    ans = 0

