            row_forbidden = set(a[i][:j]) if j > 0 else set()

            # Value from column above (vertical constraint)
            col_forbidden = {a[i-1][j]} if i > 0 else set()

            # Count valid values smaller than a[i][j]
            smaller_valid = 0
            for v in range(1, self_val):
