        return '0\n'

    lines = input_string.strip().split('\n')
    first_line = lines[0].split()
    N, M, K = int(first_line[0]), int(first_line[1]), int(first_line[2])

    transformers = []
    for i in range(K):
        parts = lines[1 + i].split()
        x, y, d, t, e_val = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
        transformers.append((x, y, d, t, e_val))

    # encounter[r][c] = total energy of all transformers at position (r,c)
    # when Blackout arrives at time = r + c
    encounter = [[0] * M for _ in range(N)]

    for (tx, ty, td, tst, ene) in transformers:
        for r in range(N):
            for c in range(M):
                T_bout = r + c
                if T_bout >= tst:
                    k = T_bout - tst
                    offset = k % 4

                    if offset == 0:
                        pos_x, pos_y = tx, ty
                    elif offset == 1:
                        pos_x, pos_y = tx + td, ty - td
                    elif offset == 2:
                        pos_x, pos_y = tx + td, ty
                    else:
                        pos_x, pos_y = tx, ty + td

                    encounter[r][c] += ene

    # DP: minimum energy to reach (r,c)
    dp = [[float('inf')] * M for _ in range(N)]
    dp[0][0] = encounter[0][0]

    for r in range(N):
        for c in range(M):
            if r > 0:
                dp[r][c] = min(dp[r][c], dp[r-1][c] + encounter[r][c])
            if c > 0:
                dp[r][c] = min(dp[r][c], dp[r][c-1] + encounter[r][c])

    return str(dp[N-1][M-1])
