    t = int(lines[0])
    pos_idx = 1

    results = []

    for _ in range(t):
        n = int(lines[pos_idx])
        pos_idx += 1
        start_str = lines[pos_idx]
        pos_idx += 1
        start_value = int(start_str)

        cat = []
        for i in range(n):
            cat.append(lines[pos_idx])
            pos_idx += 1

        # For each starting value at t=0, what character sequences do we get?
        # Two starting values are indistinguishable at t=0 if they produce same chars
        # We need to find when all ambiguous pairs become distinguishable

        mod = 10 ** n
        start_chars = []
        for i in range(n):
            start_chars.append(cat[i][start_value % 10])

        # Find all values that produce same initial character sequence
        same_display_values = set()
        same_display_values.add(start_value)

        for val in range(mod):
            val_chars = []
            for i in range(n):
                d = val % 10
                val_chars.append(cat[i][d])
            if val_chars == start_chars:
                same_display_values.add(val)

        same_display_values = sorted(list(same_display_values))

        # If only one value has same display, answer is 0
        if len(same_display_values) <= 1:
            results.append("0")
            continue

        # For each pair of indistinguishable starting values, find when they become distinguishable
        max_time = 0

        for i in range(len(same_display_values)):
            for j in range(i + 1, len(same_display_values)):
                v1, v2 = same_display_values[i], same_display_values[j]

                # Find first time t where displays differ
                t = 0
                while True:
                    v1_val = (v1 + t) % mod
                    v2_val = (v2 + t) % mod

                    v1_disp = []
                    for p in range(n):
                        v1_disp.append(cat[p][v1_val % 10])

                    v2_disp = []
                    for p in range(n):
                        v2_disp.append(cat[p][v2_val % 10])

                    if v1_disp != v2_disp:
                        # Distinguishable at time t
                        max_time = max(max_time, t)
                        break

                    t += 1
                    # Safety limit
                    if t > mod:
                        break
                else:
                    cycle = mod
                    max_time = max(max_time, cycle)

        results.append(str(max_time))

    return '\n'.join(results)
