def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 1:
        return ''

    D = int(lines[0])
    q = int(lines[1])
    queries = []

    for i in range(2, 2 + q):
        if i < len(lines):
            parts = lines[i].strip().split()
            if len(parts) >= 2:
                v, u = int(parts[0]), int(parts[1])
                queries.append((v, u))

    MOD = 998244353

    def power(a, b, m):
        result = 1
        a %= m
        while b > 0:
            if b % 2 == 1:
                result = (result * a) % m
            a = (a * a) % m
            b //= 2
        return result

    def get_prime_exponents(n):
        if n == 1:
            return {}
        factors = {}
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors[d] = factors.get(d, 0) + 1
                n //= d
            d += 1
        if n > 1:
            factors[n] = factors.get(n, 0) + 1
        return factors

    MAX_SPACE = 30000
    fact = [1] * MAX_SPACE
    inv = [1] * MAX_SPACE

    for i in range(1, MAX_SPACE):
        fact[i] = (fact[i-1] * i) % MOD

    inv[MAX_SPACE-1] = power(fact[MAX_SPACE-1], MOD - 2, MOD)
    for i in range(MAX_SPACE - 2, -1, -1):
        inv[i] = (inv[i+1] * (i + 1)) % MOD

    def nCr_mod(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv[r] % MOD * inv[n-r] % MOD

    results = []

    for v, u in queries:
        if v == u:
            results.append('1')
            continue

        v_factors = get_prime_exponents(v)
        u_factors = get_prime_exponents(u)

        ways = 1

        for p in set(v_factors.keys()) | set(u_factors.keys()):
            exp_v = v_factors.get(p, 0)
            exp_u = u_factors.get(p, 0)
            ways = (ways * nCr_mod(exp_v + exp_u, min(exp_v, exp_u))) % MOD

        results.append(str(ways))

    return '\n'.join(results)
